def binary_search(nums: list[int], target: int) -> int:
    """Searches a sorted integer sequence using midpoint halving."""
    if not nums:
        return -1
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return lo if nums[lo] == target else -1

