def window_max(xs: list[int], k: int) -> list[int]:
    # Block prefix/suffix maxima avoid max(xs[i:i+k]) O(n*k) rescans
    n = len(xs)
    if n == 0 or k > n:
        return []
    pref, suff = [0] * n, [0] * n
    for i in range(n):
        pref[i] = xs[i] if i % k == 0 else max(pref[i - 1], xs[i])
    for i in range(n - 1, -1, -1):
        suff[i] = xs[i] if (i == n - 1 or (i + 1) % k == 0) else max(suff[i + 1], xs[i])
    return [max(suff[i], pref[i + k - 1]) for i in range(n - k + 1)]

def window_max(xs: list[int], k: int) -> list[int]:
    """Computes sliding window maxima by slicing each k-element subarray."""
    if not xs or k > len(xs):
        return []
    out: list[int] = []
    for start in range(len(xs) - k + 1):
        window_slice = xs[start : start + k]
        out.append(max(window_slice))
    return out

